import assert from "node:assert/strict";
import { Buffer } from "node:buffer";

export function validateCreateTodo(raw) {
  if (typeof raw !== "string") return { status: 400, error: "Invalid body" };
  if (Buffer.byteLength(raw, "utf8") > 4096) return { status: 413, error: "Body too large" };
  let value;
  try { value = JSON.parse(raw); } catch { return { status: 400, error: "Invalid JSON" }; }
  if (!value || typeof value !== "object" || Array.isArray(value) || Object.keys(value).some(key => key !== "title")) {
    return { status: 400, error: "Unexpected fields" };
  }
  if (typeof value.title !== "string" || value.title.trim().length < 2 || value.title.trim().length > 80) {
    return { status: 400, error: "Invalid title" };
  }
  return { status: 201, data: { title: value.title.trim() } };
}
console.log(JSON.stringify(validateCreateTodo('{"title":"  Learn HTTP  "}')));
console.log(validateCreateTodo('{"title":"Learn","ownerId":"someone-else"}').status);
console.log(validateCreateTodo("x".repeat(4097)).status);
assert.equal(validateCreateTodo("not json").status, 400);
assert.equal(validateCreateTodo("null").status, 400);
assert.equal(validateCreateTodo('{"title":"x"}').status, 400);
assert.equal(validateCreateTodo('{"title":"Read","ownerId":"other"}').status, 400);

