import assert from "node:assert/strict";

export async function readOwnedTodo(session, id, repository) {
  if (!session || typeof session.userId !== "string" || !session.userId) return { status: 401 };
  if (!Number.isSafeInteger(id) || id < 1) return { status: 400 };
  const todo = await repository.findById(id);
  if (!todo || todo.ownerId !== session.userId) return { status: 404 };
  return { status: 200, data: { id: todo.id, title: todo.title } };
}
const repository = { findById: async id => id === 7 ? { id: 7, ownerId: "user-a", title: "Private task" } : null };
console.log(JSON.stringify(await readOwnedTodo({ userId: "user-a" }, 7, repository)));
console.log((await readOwnedTodo(null, 7, repository)).status);
console.log((await readOwnedTodo({ userId: "user-b" }, 7, repository)).status);
assert.deepEqual(await readOwnedTodo({ userId: "user-a" }, 99, repository), { status: 404 });
assert.deepEqual(await readOwnedTodo({ userId: "user-a" }, -1, repository), { status: 400 });
assert.deepEqual(await readOwnedTodo(null, 7, { findById: () => { throw new Error("Must not query"); } }), { status: 401 });
assert.deepEqual(await readOwnedTodo({ userId: "user-b" }, 7, repository), { status: 404 });

