import assert from "node:assert/strict";
import { createServer } from "node:http";
import { randomBytes } from "node:crypto";

// Local integration fixture: temporary opaque session and in-memory repository.
const token = randomBytes(32).toString("hex");
const sessions = new Map([[token, { userId: "learner-1", expiresAt: Date.now() + 60000 }]]);
const saved = [];
const server = createServer(async (request, response) => {
  const reply = (status, data) => {
    response.writeHead(status, { "Content-Type": "application/json", "Cache-Control": "no-store", "X-Content-Type-Options": "nosniff" });
    response.end(JSON.stringify(data));
  };
  try {
    if (request.url !== "/todos") return reply(404, { error: "Not found" });
    if (request.method !== "POST") { response.setHeader("Allow", "POST"); return reply(405, { error: "Method not allowed" }); }
    const authorization = request.headers.authorization ?? "";
    const session = sessions.get(authorization.startsWith("Bearer ") ? authorization.slice(7) : "");
    if (!session || session.expiresAt <= Date.now()) return reply(401, { error: "Unauthorized" });
    if ((request.headers["content-type"] ?? "").split(";")[0].trim() !== "application/json") return reply(415, { error: "Use JSON" });
    const chunks = []; let bytes = 0;
    for await (const chunk of request) { bytes += chunk.length; if (bytes <= 4096) chunks.push(chunk); }
    if (bytes > 4096) return reply(413, { error: "Body too large" });
    let body;
    try { body = JSON.parse(Buffer.concat(chunks).toString("utf8")); } catch { return reply(400, { error: "Invalid JSON" }); }
    if (!body || typeof body !== "object" || Array.isArray(body) || Object.keys(body).some(key => key !== "title") || typeof body.title !== "string" || body.title.trim().length < 2 || body.title.trim().length > 80) return reply(400, { error: "Invalid title" });
    const todo = { id: saved.length + 1, title: body.title.trim(), ownerId: session.userId };
    saved.push(todo);
    return reply(201, { id: todo.id, title: todo.title });
  } catch { if (!response.headersSent) reply(500, { error: "Request failed" }); }
});
server.requestTimeout = 2000;
server.headersTimeout = 2000;
server.timeout = 2500;
await new Promise(resolve => server.listen(0, "127.0.0.1", resolve));
try {
  const url = `http://127.0.0.1:${server.address().port}/todos`;
  const headers = { Authorization: `Bearer ${token}`, "Content-Type": "application/json" };
  assert.equal((await fetch(url, { method: "POST", body: "{}" })).status, 401);
  assert.equal((await fetch(url)).status, 405);
  assert.equal((await fetch(url, { method: "POST", headers, body: "{" })).status, 400);
  assert.equal((await fetch(url, { method: "POST", headers, body: "x".repeat(4097) })).status, 413);
  assert.equal((await fetch(url, { method: "POST", headers, body: JSON.stringify({ title: "Read", ownerId: "other" }) })).status, 400);
  const success = await fetch(url, { method: "POST", headers, body: JSON.stringify({ title: "  Read HTTP  " }) });
  assert.equal(success.status, 201);
  assert.equal(success.headers.get("cache-control"), "no-store");
  assert.deepEqual(await success.json(), { id: 1, title: "Read HTTP" });
  assert.equal(saved[0].ownerId, "learner-1");
  console.log("HTTP checks passed");
} finally { await new Promise((resolve, reject) => server.close(error => error ? reject(error) : resolve())); }

